SELECT review_no, request_no, sitter_email, writer_email, rating, content, reg_time
FROM tbl_babysitter_review
WHERE request_no = #{requestNo}

SELECT AVG(rating)
FROM tbl_babysitter_review
WHERE sitter_email = #{sitterEmail}

SELECT COUNT(*)
FROM tbl_babysitter_review
WHERE sitter_email = #{sitterEmail}
